mapper.select:
SELECT o.account_id AS accountId, o.marketing_task_id AS marketingTaskId, mt.task_name AS taskName, mt.task_end_at AS taskEndAt, o.occupied_at AS occupiedAt FROM marketing_account_occupancy o JOIN marketing_task mt ON mt.id = o.marketing_task_id AND mt.deleted_at IS NULL LEFT JOIN group_pull_marketing_task gp ON gp.marketing_task_id = mt.id WHERE o.account_id IN
#{accountId}
AND ( (mt.business_type = 1 AND mt.status IN (1, 2, 5)) OR (mt.business_type = 2 AND gp.resource_status IN (2, 3)) ) ORDER BY o.account_id ASC

mapper.delete:
DELETE FROM marketing_account_occupancy
WHERE marketing_task_id = #{taskId}
  AND account_id = #{accountId}
